import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CRfKVJQk.js";const u=JSON.parse('{"title":"06 · Decisions (ADRs)","description":"Short records of choices that look odd without context.","frontmatter":{"description":"Short records of choices that look odd without context.","head":[["link",{"rel":"canonical","href":"https://sachinmeenasipl.github.io/react-native-glass-effect/architecture/06-decisions"}],["meta",{"property":"og:url","content":"https://sachinmeenasipl.github.io/react-native-glass-effect/architecture/06-decisions"}],["meta",{"property":"og:title","content":"06 · Decisions (ADRs) · Liquid Glass for React Native"}],["meta",{"property":"og:description","content":"Short records of choices that look odd without context."}],["meta",{"name":"twitter:title","content":"06 · Decisions (ADRs) · Liquid Glass for React Native"}],["meta",{"name":"twitter:description","content":"Short records of choices that look odd without context."}]]},"headers":[],"relativePath":"architecture/06-decisions.md","filePath":"architecture/06-decisions.md"}'),i={name:"architecture/06-decisions.md"};function s(n,e,d,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="_06-·-decisions-adrs" tabindex="-1">06 · Decisions (ADRs) <a class="header-anchor" href="#_06-·-decisions-adrs" aria-label="Permalink to &quot;06 · Decisions (ADRs)&quot;">​</a></h1><p>Short records of choices that look odd without context.</p><h3 id="adr-001-·-android-is-the-primary-renderer" tabindex="-1">ADR-001 · Android is the primary renderer <a class="header-anchor" href="#adr-001-·-android-is-the-primary-renderer" aria-label="Permalink to &quot;ADR-001 · Android is the primary renderer&quot;">​</a></h3><p>iOS has system glass; Android has nothing. The value of this library is the Android renderer, so that&#39;s where the complexity lives. iOS maps props onto system effects.</p><h3 id="adr-002-·-explicit-glassbackdrop-instead-of-automatic-screen-capture" tabindex="-1">ADR-002 · Explicit <code>&lt;GlassBackdrop&gt;</code> instead of automatic screen capture <a class="header-anchor" href="#adr-002-·-explicit-glassbackdrop-instead-of-automatic-screen-capture" aria-label="Permalink to &quot;ADR-002 · Explicit `&lt;GlassBackdrop&gt;` instead of automatic screen capture&quot;">​</a></h3><p>A view cannot read what&#39;s behind it. Options were (a) capture the whole window, (b) an explicit source view. (a) needs pixel readback (<code>PixelCopy</code>), is async, lags a frame, and captures the glass itself. (b) gives live, same-frame, GPU-only sampling via RenderNodes, and is what mature Android blur libraries converge on. Cost: one wrapper component and one rule (&quot;glass goes outside the backdrop&quot;). We accept it and make the failure mode safe (solid fallback + clear log).</p><h3 id="adr-003-·-materials-are-resolved-in-js" tabindex="-1">ADR-003 · Materials are resolved in JS <a class="header-anchor" href="#adr-003-·-materials-are-resolved-in-js" aria-label="Permalink to &quot;ADR-003 · Materials are resolved in JS&quot;">​</a></h3><p>Native receives flat numbers. New materials, theme overrides and dark-mode variants need no native release, and both platforms stay consistent.</p><h3 id="adr-004-·-view-managers-extend-reactviewmanager-no-codegen-delegate" tabindex="-1">ADR-004 · View managers extend <code>ReactViewManager</code> (no codegen delegate) <a class="header-anchor" href="#adr-004-·-view-managers-extend-reactviewmanager-no-codegen-delegate" aria-label="Permalink to &quot;ADR-004 · View managers extend `ReactViewManager` (no codegen delegate)&quot;">​</a></h3><p>A codegen delegate only sets the spec&#39;s props plus base props. Glass must support every <code>&lt;View&gt;</code> prop (<code>pointerEvents</code>, <code>overflow</code>, <code>hitSlop</code>, …), which <code>ReactViewManager</code> implements with <code>@ReactProp</code>. With no delegate, RN uses its reflection setter, so both sets work. The codegen spec still produces the Fabric C++ props. <code>nativeContract.test.ts</code> keeps the names in sync.</p><h3 id="adr-005-·-press-squish-on-the-canvas-not-the-view-transform" tabindex="-1">ADR-005 · Press squish on the canvas, not the View transform <a class="header-anchor" href="#adr-005-·-press-squish-on-the-canvas-not-the-view-transform" aria-label="Permalink to &quot;ADR-005 · Press squish on the canvas, not the View transform&quot;">​</a></h3><p>RN styles, <code>Animated</code> and Reanimated all write <code>View.scaleX/Y/translation</code>. Writing them from native would fight user animations. Scaling the canvas in <code>draw()</code> is invisible to them.</p><h3 id="adr-006-·-three-tiers-not-android-12-only" tabindex="-1">ADR-006 · Three tiers, not &quot;Android 12+ only&quot; <a class="header-anchor" href="#adr-006-·-three-tiers-not-android-12-only" aria-label="Permalink to &quot;ADR-006 · Three tiers, not &quot;Android 12+ only&quot;&quot;">​</a></h3><p>AGSL needs API 33; <code>RenderEffect</code> blur needs 31. Most of the installed base in several markets is still ≤ 30. A throttled snapshot renderer keeps the design language everywhere, and <code>quality</code> lets apps opt down.</p><h3 id="adr-007-·-zero-runtime-dependencies" tabindex="-1">ADR-007 · Zero runtime dependencies <a class="header-anchor" href="#adr-007-·-zero-runtime-dependencies" aria-label="Permalink to &quot;ADR-007 · Zero runtime dependencies&quot;">​</a></h3><p>No Reanimated or Skia peer deps. Animations are native (Android) or <code>Animated</code> (JS button). This keeps install friction minimal.</p><h3 id="adr-008-·-new-architecture-only" tabindex="-1">ADR-008 · New Architecture only <a class="header-anchor" href="#adr-008-·-new-architecture-only" aria-label="Permalink to &quot;ADR-008 · New Architecture only&quot;">​</a></h3><p>Fabric view managers + TurboModules. The old bridge is not supported (RN ≥ 0.76 defaults to the New Architecture).</p>',18)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
